/* Attd05Mapper.selectUserList */ WITH RECURSIVE node_tree AS ( /* 로그인 사용자의 node 부터 시작 */ SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
/* 하위 노드 무한 확장 */ SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD )
SELECT '' AS chk , A.CMPNY_CD AS cmpnyCd , A.USER_CD AS userCd , A.USER_ID AS userId , A.USER_NM AS userNm , A.SITE_CD AS siteCd , A.NODE_CD AS nodeCd , B.NODE_NM AS nodeNm , '' AS shiftTeam , A.MBL_NO_ENC AS mblNo FROM TB_USER A INNER JOIN node_tree B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.SITE_CD = B.SITE_CD AND A.NODE_CD = B.NODE_CD ) WHERE A.ACCOUNT_STATUS != '03' /* 일용직(EMPLOYMENT_TYPE='DAILY')은 근무계획 그리드 대상이 아니므로 목록에서 제외한다. */ AND IFNULL(A.EMPLOYMENT_TYPE, '') != 'DAILY'
AND A.USER_NM LIKE CONCAT('%', #{userNm}, '%')
AND A.NODE_CD = #{nodeCd}

/* Attd05Mapper.selectSchedList */ /* 조회 그리드(selectUserList)와 동일한 사용자 스코프(부서 노드트리 + 하위포함/사용자명) 와 조회월(workYm)로 제한한다. 과거(사업장 전체/전월) 근무계획이 프론트로 흘러가 저장 시 무관한 셀까지 재저장되는 문제를 차단한다. */ WITH RECURSIVE node_tree AS ( /* 조회 부서부터 시작 */ SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
/* 하위 노드 무한 확장 */ SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD ) SELECT A.CMPNY_CD AS cmpnyCd , A.SITE_CD AS siteCd , A.USER_CD AS userCd , A.WORK_YMD AS wrkYmd , A.WORK_PLAN_CD AS workPlanCd FROM TB_USER_WORK_PLAN A INNER JOIN TB_USER U ON U.CMPNY_CD = A.CMPNY_CD AND U.SITE_CD = A.SITE_CD AND U.USER_CD = A.USER_CD INNER JOIN node_tree B ON U.CMPNY_CD = B.CMPNY_CD AND U.SITE_CD = B.SITE_CD AND U.NODE_CD = B.NODE_CD WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.SITE_CD = #{siteCd} AND A.WORK_YMD LIKE CONCAT(REPLACE(#{workYm}, '-', ''), '%') AND U.ACCOUNT_STATUS != '03'
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
AND U.NODE_CD = #{nodeCd}

/* Attd05Mapper.selectLeaveOverlayList */ /* prafta-com-008-E-6: 그리드 연차 오버레이. 조회월의 각 일자에 대해, 조회 스코프(노드트리/사업장/사용자명) 사용자의 종일 확정 연차(leave_use START_DATE~END_DATE 구간 포함)를 (userCd, workYmd, leaveCd) 로 펼쳐 반환한다. work_plan 의 코드(SCH_CD)와 무관하게 셀의 "연차" 표시 단일 출처(E-2). */ WITH RECURSIVE date_range AS ( SELECT STR_TO_DATE(CONCAT(REPLACE(#{workYm}, '-', ''), '01'), '%Y%m%d') AS dt UNION ALL SELECT DATE_ADD(dt, INTERVAL 1 DAY) FROM date_range WHERE DATE_ADD(dt, INTERVAL 1 DAY) <= LAST_DAY(STR_TO_DATE(CONCAT(REPLACE(#{workYm}, '-', ''), '01'), '%Y%m%d')) ), node_tree AS ( SELECT N.CMPNY_CD, N.SITE_CD, N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
SELECT C.CMPNY_CD, C.SITE_CD, C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD ) SELECT U.USER_CD AS userCd , DATE_FORMAT(d.dt, '%Y%m%d') AS workYmd , L.LEAVE_CD AS leaveCd , L.LEAVE_ID AS leaveId FROM date_range d INNER JOIN TB_USER_LEAVE_USE L ON L.CMPNY_CD = #{gvCmpnyCd} AND L.LEAVE_STATUS = 'CONFIRMED' AND L.DEL_YN = 'N' AND L.USE_UNIT_TYPE = '00' AND DATE_FORMAT(d.dt, '%Y%m%d') >= L.START_DATE AND DATE_FORMAT(d.dt, '%Y%m%d') <= L.END_DATE INNER JOIN TB_USER U ON U.CMPNY_CD = L.CMPNY_CD AND U.USER_CD = L.USER_CD INNER JOIN node_tree B ON U.CMPNY_CD = B.CMPNY_CD AND U.SITE_CD = B.SITE_CD AND U.NODE_CD = B.NODE_CD WHERE U.SITE_CD = #{siteCd} AND U.ACCOUNT_STATUS != '03'
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
AND U.NODE_CD = #{nodeCd}

/* Attd05Mapper.selectPartialLeaveOverlayList */ /* 그리드 부분 휴가(반차/시간차) 오버레이. 종일(USE_UNIT_TYPE='00')은 selectLeaveOverlayList 가 셀 값을 "연차"로 대체하지만, 반차/시간차(USE_UNIT_TYPE != '00')는 근무 스케줄(SCH_CD)이 살아있으므로 셀 값을 덮지 않고 (userCd, workYmd) 키에 사용단위/시간대/사용분을 동반해 셀 위에 칩으로만 표시한다. 스코프 술어/조인은 selectLeaveOverlayList 와 동일(노드트리/사업장/사용자명/계정상태). */ WITH RECURSIVE date_range AS ( SELECT STR_TO_DATE(CONCAT(REPLACE(#{workYm}, '-', ''), '01'), '%Y%m%d') AS dt UNION ALL SELECT DATE_ADD(dt, INTERVAL 1 DAY) FROM date_range WHERE DATE_ADD(dt, INTERVAL 1 DAY) <= LAST_DAY(STR_TO_DATE(CONCAT(REPLACE(#{workYm}, '-', ''), '01'), '%Y%m%d')) ), node_tree AS ( SELECT N.CMPNY_CD, N.SITE_CD, N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
SELECT C.CMPNY_CD, C.SITE_CD, C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD ) SELECT U.USER_CD AS userCd , DATE_FORMAT(d.dt, '%Y%m%d') AS workYmd , L.USE_UNIT_TYPE AS useUnitType , V.SYST_VAL_D_NM AS useUnitNm , L.LEAVE_CD AS leaveCd , L.START_TIME AS startTime , L.END_TIME AS endTime , L.LEAVE_MINUTES AS leaveMinutes FROM date_range d INNER JOIN TB_USER_LEAVE_USE L ON L.CMPNY_CD = #{gvCmpnyCd} AND L.LEAVE_STATUS = 'CONFIRMED' AND L.DEL_YN = 'N' AND L.USE_UNIT_TYPE != '00' AND DATE_FORMAT(d.dt, '%Y%m%d') >= L.START_DATE AND DATE_FORMAT(d.dt, '%Y%m%d') <= L.END_DATE INNER JOIN TB_USER U ON U.CMPNY_CD = L.CMPNY_CD AND U.USER_CD = L.USER_CD INNER JOIN node_tree B ON U.CMPNY_CD = B.CMPNY_CD AND U.SITE_CD = B.SITE_CD AND U.NODE_CD = B.NODE_CD LEFT JOIN TB_SYST_VAL_D V ON V.SYST_VAL_CD = 'SYS025' AND V.SYST_VAL_D_CD = L.USE_UNIT_TYPE WHERE U.SITE_CD = #{siteCd} AND U.ACCOUNT_STATUS != '03'
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
AND U.NODE_CD = #{nodeCd}

/* Attd05Mapper.selectShiftLockOverlayList */ /* prafta-com-008-D-5: 그리드 교대 잠금 오버레이. 조회월의 각 일자에 대해, 조회 스코프(노드트리/사업장/사용자명) 사용자가 교대팀 소속 구간(잠금)에 드는 (userCd, workYmd) 를 펼쳐 반환한다. ★ 판정 술어는 ShiftMembershipMapper.countShiftMembershipOn(D-1) 과 동일: - 팀 마스터(TM) STR_DATE inclusive ~ END_DATE inclusive(NULL=개방경계). - 멤버십 행(TU) 존재 ∩ 탈퇴일 미포함(LEAVE_TEAM_YMD IS NULL OR LEAVE_TEAM_YMD > 그 날). (단일출처 표류 방지를 위해 동일 경계 규칙을 그리드 월 범위로 펼친 형태만 사용한다.) */ WITH RECURSIVE date_range AS ( SELECT STR_TO_DATE(CONCAT(REPLACE(#{workYm}, '-', ''), '01'), '%Y%m%d') AS dt UNION ALL SELECT DATE_ADD(dt, INTERVAL 1 DAY) FROM date_range WHERE DATE_ADD(dt, INTERVAL 1 DAY) <= LAST_DAY(STR_TO_DATE(CONCAT(REPLACE(#{workYm}, '-', ''), '01'), '%Y%m%d')) ), node_tree AS ( SELECT N.CMPNY_CD, N.SITE_CD, N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
SELECT C.CMPNY_CD, C.SITE_CD, C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD ) SELECT DISTINCT U.USER_CD AS userCd , DATE_FORMAT(d.dt, '%Y%m%d') AS workYmd FROM date_range d INNER JOIN TB_USER U ON U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} INNER JOIN node_tree B ON U.CMPNY_CD = B.CMPNY_CD AND U.SITE_CD = B.SITE_CD AND U.NODE_CD = B.NODE_CD INNER JOIN TB_SHIFT_SCH_TEAM_USER TU ON TU.CMPNY_CD = U.CMPNY_CD AND TU.USER_CD = U.USER_CD INNER JOIN TB_SHIFT_SCH_TEAM_MGMT TM ON TM.CMPNY_CD = TU.CMPNY_CD AND TM.SITE_CD = TU.SITE_CD AND TM.SHIFT_CD = TU.SHIFT_CD AND TM.SHIFT_TEAM_ID = TU.SHIFT_TEAM_ID WHERE U.ACCOUNT_STATUS != '03' AND (TM.STR_DATE IS NULL OR TM.STR_DATE <= DATE_FORMAT(d.dt, '%Y%m%d')) AND (TM.END_DATE IS NULL OR TM.END_DATE >= DATE_FORMAT(d.dt, '%Y%m%d')) AND (TU.LEAVE_TEAM_YMD IS NULL OR TU.LEAVE_TEAM_YMD > DATE_FORMAT(d.dt, '%Y%m%d'))
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
AND U.NODE_CD = #{nodeCd}

/* Attd05Mapper.selectSchTypeUseYnList */ /* 근무타입(SCH_CD) effective-dating 검증용 버전 목록. TB_SCH_MGMT(현재본) 과 TB_SCH_MGMT_HIST(이력본)를 UNION 으로 합쳐 동일 SCH_CD + APPLY_DATE 가 중복되면 HIST_IDX 최댓값 1건만 채택한다. attd07 과 달리 USE_YN='N' 버전도 차단 근거로 살려야 하므로 USE_YN 필터를 걸지 않고 USE_YN 을 컬럼으로 SELECT 해 판정에 사용한다. */ SELECT E.SCH_CD AS schCd , E.APPLY_DATE AS applyDate , E.USE_YN AS useYn FROM ( /* 현재본 (HIST_IDX 를 최댓값으로 두어 동일 APPLY_DATE 중복 시 현재본 우선) */ SELECT M.CMPNY_CD , M.SITE_CD , M.SCH_CD , M.APPLY_DATE , M.USE_YN , 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M WHERE M.CMPNY_CD = #{gvCmpnyCd} AND M.SITE_CD = #{siteCd}
UNION ALL
/* 이력본 */ SELECT H.CMPNY_CD , H.SITE_CD , H.SCH_CD , H.APPLY_DATE , H.USE_YN , H.HIST_IDX FROM TB_SCH_MGMT_HIST H WHERE H.CMPNY_CD = #{gvCmpnyCd} AND H.SITE_CD = #{siteCd} ) E /* 동일 SCH_CD + APPLY_DATE 그룹에서 HIST_IDX 최댓값 행만 채택 */ WHERE E.HIST_IDX = ( SELECT MAX(E2.HIST_IDX) FROM ( SELECT M2.CMPNY_CD, M2.SITE_CD, M2.SCH_CD, M2.APPLY_DATE, 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M2 WHERE M2.CMPNY_CD = #{gvCmpnyCd} AND M2.SITE_CD = #{siteCd} UNION ALL SELECT H2.CMPNY_CD, H2.SITE_CD, H2.SCH_CD, H2.APPLY_DATE, H2.HIST_IDX FROM TB_SCH_MGMT_HIST H2 WHERE H2.CMPNY_CD = #{gvCmpnyCd} AND H2.SITE_CD = #{siteCd} ) E2 WHERE E2.CMPNY_CD = E.CMPNY_CD AND E2.SITE_CD = E.SITE_CD AND E2.SCH_CD = E.SCH_CD AND E2.APPLY_DATE = E.APPLY_DATE ) ORDER BY E.SCH_CD, E.APPLY_DATE

/* Attd05Mapper.selectLegalLeaveCds */
SELECT A.LEAVE_CD
  FROM TB_LEAVE_TYPE_MGMT A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.USE_YN = 'Y'
   AND A.LEAVE_NATURE_TYPE = '01'

mapper.update:
    /* Attd05Mapper.saveUserWorkPlans */
	INSERT INTO TB_USER_WORK_PLAN (
	    CMPNY_CD
	    , SITE_CD
	    , USER_CD
	    , WORK_YMD
	    , WORK_PLAN_CD
	    , INSERT_NO
	    , INSERT_DATE
	    , UPDATE_NO
	    , UPDATE_DATE
	) VALUES (
	    #{gvCmpnyCd}
	    , #{siteCd}
	    , #{userCd}
	    , #{workYmd}
	    , #{workPlanCd}
	    , #{gvUserCd}
	    , NOW()
	    , #{gvUserCd}
	    , NOW()
	) AS NEW
	ON DUPLICATE KEY UPDATE
		WORK_PLAN_CD	= NEW.WORK_PLAN_CD
	    , UPDATE_NO		= NEW.UPDATE_NO
	    , UPDATE_DATE	= NOW()

mapper.select:
/* Attd05Mapper.selectMonthOvertimeDays */
SELECT DISTINCT T.WORK_YMD FROM (
    SELECT OM.WORK_YMD AS WORK_YMD
      FROM TB_USER_OVERTIME_MGMT OM
     WHERE OM.CMPNY_CD = #{cmpnyCd}
       AND OM.SITE_CD  = #{siteCd}
       AND OM.USER_CD  = #{userCd}
       AND LEFT(OM.WORK_YMD, 6) = #{workYm}
       AND OM.DEL_YN   = 'N'
       AND OM.OT_STATUS  <>  'CANCELLED'
    UNION ALL
    SELECT RQ.WORK_YMD AS WORK_YMD
      FROM TB_USER_ATTD_REQ RQ
     WHERE RQ.CMPNY_CD = #{cmpnyCd}
       AND RQ.SITE_CD  = #{siteCd}
       AND RQ.USER_CD  = #{userCd}
       AND LEFT(RQ.WORK_YMD, 6) = #{workYm}
       AND RQ.DEL_YN   = 'N'
       AND RQ.REQ_TYPE IN ('03', '04')
       AND RQ.REQ_STATUS IN ('01', '02')
) T
ORDER BY T.WORK_YMD

/* Attd05Mapper.selectMonthLeaveDays */
SELECT DISTINCT WP.WORK_YMD
  FROM TB_USER_WORK_PLAN WP
 WHERE WP.CMPNY_CD = #{cmpnyCd}
   AND WP.SITE_CD  = #{siteCd}
   AND WP.USER_CD  = #{userCd}
   AND LEFT(WP.WORK_YMD, 6) = #{workYm}
   AND EXISTS (
         SELECT 1
           FROM TB_USER_LEAVE_USE U
          WHERE U.CMPNY_CD      = WP.CMPNY_CD
            AND U.USER_CD       = WP.USER_CD
            AND U.LEAVE_STATUS  = 'CONFIRMED'
            AND U.DEL_YN        = 'N'
            AND U.USE_UNIT_TYPE = '00'
            AND U.START_DATE    <=  WP.WORK_YMD
            AND U.END_DATE      >=  WP.WORK_YMD
       )
 ORDER BY WP.WORK_YMD

/* Attd05Mapper.selectWorkPlanCellCd */
SELECT WORK_PLAN_CD
  FROM TB_USER_WORK_PLAN
 WHERE CMPNY_CD = #{gvCmpnyCd}
   AND SITE_CD  = #{siteCd}
   AND USER_CD  = #{userCd}
   AND WORK_YMD = #{workYmd}

mapper.delete:
/* Attd05Mapper.deleteUserWorkPlanCell */
DELETE FROM TB_USER_WORK_PLAN
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD  = #{siteCd}
  AND USER_CD  = #{userCd}
  AND WORK_YMD = #{workYmd}

mapper.select:
/* Attd05Mapper.selectUserDefaultSchCd */
SELECT U.DEFAULT_SCH_CD
  FROM TB_USER U
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.USER_CD  = #{userCd}
 LIMIT 1

/* Attd05Mapper.countFullDayLeaveUseOnCell */
SELECT COUNT(*)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD      = #{cmpnyCd}
   AND U.USER_CD       = #{userCd}
   AND U.LEAVE_STATUS  = 'CONFIRMED'
   AND U.DEL_YN        = 'N'
   AND U.USE_UNIT_TYPE = '00'
   AND U.START_DATE   <= #{workYmd}
   AND U.END_DATE     >= #{workYmd}

/* Attd05Mapper.selectDirectFullDayLeaveCdOnCell */
SELECT U.LEAVE_CD
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD      = #{cmpnyCd}
   AND U.USER_CD       = #{userCd}
   AND U.START_DATE    = #{workYmd}
   AND U.REQ_ID IS NULL
   AND U.LEAVE_STATUS  = 'CONFIRMED'
   AND U.DEL_YN        = 'N'
   AND U.USE_UNIT_TYPE = '00'
 LIMIT 1

/* Attd05Mapper.selectApprovedFullDayLeaveCdOnCell */
SELECT U.LEAVE_CD
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD      = #{cmpnyCd}
   AND U.USER_CD       = #{userCd}
   AND U.START_DATE    = #{workYmd}
   AND U.REQ_ID IS NOT NULL
   AND U.LEAVE_STATUS  = 'CONFIRMED'
   AND U.DEL_YN        = 'N'
   AND U.USE_UNIT_TYPE = '00'
 LIMIT 1

/* Attd05Mapper.selectFullDayLeaveCdOnCell */
SELECT U.LEAVE_CD
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD      = #{cmpnyCd}
   AND U.USER_CD       = #{userCd}
   AND U.LEAVE_STATUS  = 'CONFIRMED'
   AND U.DEL_YN        = 'N'
   AND U.USE_UNIT_TYPE = '00'
   AND U.START_DATE   <= #{workYmd}
   AND U.END_DATE     >= #{workYmd}
 LIMIT 1

/* Attd05Mapper.countUserWorkPlanSchedule */
SELECT COUNT(1)
  FROM TB_USER_WORK_PLAN WP
 INNER JOIN TB_SCH_MGMT SM
    ON SM.CMPNY_CD = WP.CMPNY_CD
   AND SM.SITE_CD  = WP.SITE_CD
   AND SM.SCH_CD   = WP.WORK_PLAN_CD
 WHERE WP.CMPNY_CD = #{cmpnyCd}
   AND WP.SITE_CD  = #{siteCd}
   AND WP.USER_CD  = #{userCd}
   AND WP.WORK_YMD = #{workYmd}

/* Attd05Mapper.countDayOvertime */
SELECT (
         (
           SELECT COUNT(1)
             FROM TB_USER_OVERTIME_MGMT OM
            WHERE OM.CMPNY_CD = #{cmpnyCd}
              AND OM.SITE_CD  = #{siteCd}
              AND OM.USER_CD  = #{userCd}
              AND OM.WORK_YMD = #{workYmd}
              AND OM.DEL_YN   = 'N'
              AND OM.OT_STATUS <> 'CANCELLED'
         )
         +
         (
           SELECT COUNT(1)
             FROM TB_USER_ATTD_REQ RQ
            WHERE RQ.CMPNY_CD = #{cmpnyCd}
              AND RQ.SITE_CD  = #{siteCd}
              AND RQ.USER_CD  = #{userCd}
              AND RQ.WORK_YMD = #{workYmd}
              AND RQ.DEL_YN   = 'N'
              AND RQ.REQ_TYPE IN ('03', '04')
              AND RQ.REQ_STATUS IN ('01', '02')
         )
       ) AS OT_CNT

/* Attd05Mapper.countMonthOvertime */
SELECT (
         (
           SELECT COUNT(1)
             FROM TB_USER_OVERTIME_MGMT OM
            WHERE OM.CMPNY_CD = #{cmpnyCd}
              AND OM.SITE_CD  = #{siteCd}
              AND OM.USER_CD  = #{userCd}
              AND LEFT(OM.WORK_YMD, 6) = #{workYm}
              AND OM.DEL_YN   = 'N'
              AND OM.OT_STATUS <> 'CANCELLED'
         )
         +
         (
           SELECT COUNT(1)
             FROM TB_USER_ATTD_REQ RQ
            WHERE RQ.CMPNY_CD = #{cmpnyCd}
              AND RQ.SITE_CD  = #{siteCd}
              AND RQ.USER_CD  = #{userCd}
              AND LEFT(RQ.WORK_YMD, 6) = #{workYm}
              AND RQ.DEL_YN   = 'N'
              AND RQ.REQ_TYPE IN ('03', '04')
              AND RQ.REQ_STATUS IN ('01', '02')
         )
       ) AS OT_CNT
